// Distinct elliptic-arithmetic backend. Does not independently verify the quotient.
#include "json.hpp"
#include <openssl/bn.h>
#include <openssl/ec.h>
#include <openssl/obj_mac.h>
#include <memory>
#include <iostream>
#include <set>
using Big=std::unique_ptr<BIGNUM,decltype(&BN_free)>;
using Point=std::unique_ptr<EC_POINT,decltype(&EC_POINT_free)>;
Big decimal(const std::string&s){BIGNUM* raw=nullptr;require(!s.empty()&&BN_dec2bn(&raw,s.c_str())==int(s.size()),"OpenSSL decimal token");return Big(raw,BN_free);}
Point point(const EC_GROUP*g){Point p(EC_POINT_new(g),EC_POINT_free);require(bool(p),"OpenSSL point allocation");return p;}
Point read_point(const Json&j,const EC_GROUP*g,BN_CTX*ctx,bool corrupt=false){auto p=point(g);if(j.at("infinity").scalar=="true"){require(EC_POINT_set_to_infinity(g,p.get())==1,"OpenSSL infinity");return p;}require(j.at("infinity").scalar=="false","OpenSSL infinity flag");auto x=decimal(j.at("x").scalar),y=decimal(j.at("y").scalar);if(corrupt)require(BN_add_word(y.get(),1)==1,"canary mutation");require(EC_POINT_set_affine_coordinates(g,p.get(),x.get(),y.get(),ctx)==1&&EC_POINT_is_on_curve(g,p.get(),ctx)==1,"OpenSSL invalid point");return p;}
int main(int argc,char**argv){try{require(argc==2||(argc==3&&std::string(argv[2])=="--canary"),"usage: openssl_roundtrip_check receipt.jsonl [--canary]");bool canary=argc==3,planted=false;std::unique_ptr<EC_GROUP,decltype(&EC_GROUP_free)> group(EC_GROUP_new_by_curve_name(NID_X9_62_prime192v1),EC_GROUP_free);std::unique_ptr<BN_CTX,decltype(&BN_CTX_free)> ctx(BN_CTX_new(),BN_CTX_free);require(bool(group)&&bool(ctx),"OpenSSL group/context");Big order(BN_new(),BN_free),six(BN_new(),BN_free);require(bool(order)&&bool(six)&&EC_GROUP_get_order(group.get(),order.get(),ctx.get())==1&&BN_set_word(six.get(),6)==1,"OpenSSL group order");auto supplied=decimal("6277101735386680763835789423176059013767194773182842284081");require(BN_cmp(order.get(),supplied.get())==0,"OpenSSL source identity");Big inverse(BN_mod_inverse(nullptr,six.get(),order.get(),ctx.get()),BN_free);require(bool(inverse),"OpenSSL inverse6");std::ifstream in(argv[1]);require(bool(in),"OpenSSL receipt input");std::string line;int rows=0;std::set<std::pair<int,int>> cases;
    while(std::getline(in,line)){Parser parser{line};auto j=parser.value();int kernel=j.at("kernel").integer(),index=j.at("case").integer();require(kernel>=1&&kernel<=8&&index>=0&&index<5&&cases.emplace(kernel,index).second,"OpenSSL case identity");auto source=read_point(j.at("source"),group.get(),ctx.get()),projected=read_point(j.at("T_F_source"),group.get(),ctx.get());bool corrupt=canary&&!planted&&j.at("recovered_source").at("infinity").scalar=="false";planted|=corrupt;auto recovered=read_point(j.at("recovered_source"),group.get(),ctx.get(),corrupt),expected=point(group.get());auto scalar=decimal(j.at("known_scalar").scalar);require(EC_POINT_mul(group.get(),expected.get(),scalar.get(),nullptr,nullptr,ctx.get())==1&&EC_POINT_cmp(group.get(),expected.get(),source.get(),ctx.get())==0,"OpenSSL known-answer source binding");require(EC_POINT_mul(group.get(),expected.get(),nullptr,source.get(),six.get(),ctx.get())==1&&EC_POINT_cmp(group.get(),expected.get(),projected.get(),ctx.get())==0,"OpenSSL TF!=6");require(EC_POINT_mul(group.get(),expected.get(),nullptr,projected.get(),inverse.get(),ctx.get())==1&&EC_POINT_cmp(group.get(),expected.get(),recovered.get(),ctx.get())==0&&EC_POINT_cmp(group.get(),recovered.get(),source.get(),ctx.get())==0,"OpenSSL recovered point mismatch");++rows;
    }require(rows==40,"OpenSSL complete receipt");require(!canary,"OpenSSL canary not rejected");std::cout<<"PASS OpenSSL checks40 P-192 source/TF=[6]/inverse6 point receipts across8 kernels, including the known full-width scalar fixtures. This checks elliptic outputs only, not quotient geometry or scalar recovery.\n";
}catch(const std::exception&e){std::cerr<<"REJECT "<<e.what()<<'\n';return 1;}}
